def calculate_l1_status(bom_items, total_contract_value):
    local_content_value = 0.0

    for item in bom_items:
        # item: {unit_cost, quantity, local_percentage}
        item_total = item.unit_cost * item.quantity
        local_value = item_total * (item.local_percentage / 100.0)
        local_content_value += local_value

    local_content_percent = (local_content_value / total_contract_value) * 100

    status = 'NON_LOCAL'
    if local_content_percent >= 50.0:
        status = 'CLASS_I'
    elif local_content_percent >= 20.0:
        status = 'CLASS_II'

    return {
        'local_value': local_content_value,
        'percent': local_content_percent,
        'status': status
    }

