from rapidfuzz import fuzz

def verify_citation(draft_citation, source_text):
    # Extract snippet from draft citation
    snippet = draft_citation['snippet']

    # 1. Exact Match
    if snippet in source_text:
        return {'status': 'VERIFIED', 'method': 'EXACT'}

    # 2. Fuzzy Match
    score = fuzz.ratio(snippet, source_text)
    if score >= 95:
        return {'status': 'VERIFIED', 'method': 'FUZZY', 'score': score}

    # 3. Fail
    return {'status': 'FAILED', 'reason': 'Low confidence match'}

