    # bom_data: List of dicts {cost, local_pct}
    total_cost = sum(item['cost'] for item in bom_data)
    if total_cost == 0: return 'ERROR'

    local_val = sum(item['cost'] * (item['local_pct']/100) for item in bom_data)
    local_content_pct = (local_val / total_cost) * 100

